package com.project.entity.enterprise;
import com.project.entity.Employee; import javax.persistence.*; import java.time.LocalDate;
@Entity @Table(name="employee_documents") public class EmployeeDocument { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.EAGER) @JoinColumn(name="employee_id",nullable=false) private Employee employee; private String documentType; private String documentName; private String status="ACTIVE"; private LocalDate issueDate; private LocalDate expiryDate; private String filePath; public Long getId(){return id;} public Employee getEmployee(){return employee;} public void setEmployee(Employee v){employee=v;} public String getDocumentType(){return documentType;} public void setDocumentType(String v){documentType=v;} public String getDocumentName(){return documentName;} public void setDocumentName(String v){documentName=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} public LocalDate getIssueDate(){return issueDate;} public void setIssueDate(LocalDate v){issueDate=v;} public LocalDate getExpiryDate(){return expiryDate;} public void setExpiryDate(LocalDate v){expiryDate=v;} public String getFilePath(){return filePath;} public void setFilePath(String v){filePath=v;} }
